package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaElDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Καταφύγιο από το Κακό των Πράξεων Μου", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από το κακό αυτού που έχω κάνει και από το κακό αυτού που δεν έχω κάνει.", "Μια ντουέτα του Προφήτη ﷺ, σύμφωνα με την Aisha (RA).", "Προστασία από τις συνέπειες τόσο του γεγονότος όσο και αυτού που έμεινε ανεκπλήρωτο."),
        "dua_jahdil_bala" to DuaText("Καταφύγιο από βαριές δοκιμασίες", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από τη σκληρή δοκιμασία, από το να με κυριεύσει η δυστυχία, από ένα κακό διάταγμα και από τη δοξολογία των εχθρών.", "Καταφύγιο από τις σκληρές δοκιμασίες και τις δοξασίες των εχθρών.", "Ο Προφήτης ﷺ αναζήτησε καταφύγιο από αυτά τα τέσσερα πράγματα."),
        "dua_fitnat_ghina_faqr" to DuaText("Καταφύγιο από τις δοκιμασίες του πλούτου και της φτώχειας", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από την τεμπελιά και τα γηρατειά, από την αμαρτία και το χρέος, από τη δοκιμασία και την τιμωρία του τάφου, από τη δοκιμασία και την τιμωρία της φωτιάς, από το κακό της δοκιμασίας του πλούτου και από τη δοκιμασία της φτώχειας.", "Καταφύγιο από τις δοκιμασίες του τάφου, της κόλασης, του πλούτου και της φτώχειας (μέρος της ντουέτας).", "Μια περιεκτική ντουέτα καταφυγής από τον Προφήτη ﷺ."),
        "dua_kufr_faqr" to DuaText("Καταφύγιο από τη δυσπιστία και τη φτώχεια", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από την απιστία και τη φτώχεια και σε Σένα ζητώ καταφύγιο από την τιμωρία του τάφου. Δεν υπάρχει θεός εκτός από Εσένα.", "Τρεις φορές πρωί και βράδυ.", "Ο Abu Bakrah (RA) άκουσε τον Προφήτη ﷺ να το λέει αυτό."),
        "dua_sharri_sami" to DuaText("Καταφύγιο από το κακό των αισθήσεών μου", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από το κακό της ακοής μου, το κακό της όρασης μου, το κακό της γλώσσας μου, το κακό της καρδιάς μου και το κακό της επιθυμίας μου.", "Δίδαξε στον Shakal ibn Humayd (RA).", "Μια ντουέτα για την προστασία των άκρων και του εαυτού από την αμαρτία."),
        "dua_hadm_gharaq" to DuaText("Καταφύγιο από αιφνίδιο θάνατο και ατυχήματα", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από το να με συνθλίψει (από ένα κτίριο), να μην πέσω από ύψος, από πνιγμό, κάψιμο και γήρας. από τον Σαϊτάν που με παρέσυρε την ώρα του θανάτου, από το να πεθάνω ενώ φεύγω από το μονοπάτι Σου και από το να πεθάνω από ένα (δηλητηριώδες) τσίμπημα.", "Καταφύγιο από ατυχήματα και έναν κακό θάνατο.", "Μια ντουέτα καταφυγής από τον Προφήτη ﷺ."),
        "dua_ju_khiyanah" to DuaText("Καταφύγιο από την πείνα και την προδοσία", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από την πείνα, γιατί είναι κακός σύντροφος, και σε Σένα ζητώ καταφύγιο από την προδοσία, γιατί είναι κακός έμπιστος.", "Καταφύγιο από την πείνα και την προδοσία.", "Μια ντουέτα καταφυγής από τον Προφήτη ﷺ."),
        "dua_huda_tuqa" to DuaText("Καθοδήγηση, ευσέβεια, αγνότητα και επάρκεια", "Ω Αλλάχ, Σου ζητώ καθοδήγηση, ευσέβεια, αγνότητα και αυτάρκεια.", "Μια σύντομη, περιεκτική ντουέτα του Προφήτη ﷺ.", "Τέσσερις θεμελιώδεις ευλογίες της θρησκείας και αυτού του κόσμου."),
        "dua_aslih_li_dini" to DuaText("Διορθώστε τη Θρησκεία Μου, τον κόσμο και το εξής", "Ω Αλλάχ, διορθώστε τη θρησκεία μου, η οποία είναι η διαφύλαξη όλων των υποθέσεων μου. Διορθώστε την εγκόσμια ζωή μου, στην οποία είναι ο βιοπορισμός μου. και όρισε το Έπειτα μου, στο οποίο θα επιστρέψω. Κάνε μου τη ζωή αύξηση σε κάθε καλό, και κάνε τον θάνατο ανακούφιση από κάθε κακό.", "Μεταρρυθμίζοντας τη θρησκεία, αυτόν τον κόσμο και το επέκεινα — και τα τρία.", "Μια περιεκτική ντουέτα του Προφήτη ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Στρέψτε τις Καρδιές μας στην Υπακοή Σας", "Ω Αλλάχ, γυριστή των καρδιών, στρέψε τις καρδιές μας στην υπακοή Σου.", "Μια δόξα για να κρατήσει την καρδιά σταθερή στην υπακοή.", "Οι καρδιές όλων των ανθρώπων βρίσκονται ανάμεσα στα δύο δάχτυλα του Ελεήμονα."),
        "dua_jannah_nar" to DuaText("Ζητώντας την Τζάνα, Καταφύγιο από τη Φωτιά", "Ω Αλλάχ, Σου ζητώ τον Παράδεισο και ζητώ καταφύγιο σε Σένα από τη Φωτιά.", "Μετά το tashahhud ή οποιαδήποτε στιγμή.", "Ο Προφήτης ﷺ είπε: και οι δικές μας δέες περιστρέφονται γύρω από αυτό."),
        "dua_khayri_kullih" to DuaText("Όλα καλά, τώρα και αργότερα", "Ω Αλλάχ, Σου ζητώ όλα τα καλά — το άμεσο και το καθυστερημένο, ό,τι ξέρω και ό,τι δεν ξέρω — και καταφεύγω σε Σένα από κάθε κακό — το άμεσο και το καθυστερημένο, ό,τι ξέρω και ό,τι δεν ξέρω. Ω Αλλάχ, Σου ζητώ τον Παράδεισο και για ό,τι λόγια και πράξεις με φέρνουν κοντά σε αυτόν, και αναζητώ καταφύγιο σε Σένα από τη φωτιά και από ό,τι λόγια και πράξεις με φέρνουν κοντά σε αυτήν.", "Ο Προφήτης ﷺ δίδαξε αυτήν την περιεκτική ντουά στην Aisha (RA) (μέρος της ντουά).", "Μια ντουέτα που συγκεντρώνει κάθε καλό."),
        "dua_ihdini_saddidni" to DuaText("Οδηγήστε με και κρατήστε με όρθιο", "Ω Αλλάχ, καθοδήγησέ με και κράτησέ με στη σωστή πορεία.", "Ο Προφήτης ﷺ το δίδαξε στον Ali (RA).", "Σκεφτείτε την καθοδήγηση ως την καθοδήγηση κατά μήκος ενός δρόμου και το sadad σαν την ευθύτητα ενός βέλους."),
        "dua_hubbaka" to DuaText("Ζητώντας την Αγάπη του Αλλάχ", "Ω Αλλάχ, Σου ζητώ την αγάπη Σου, την αγάπη όσων Σε αγαπούν και πράξεις που με φέρνουν στην αγάπη Σου. Ω Αλλάχ, κάνε την αγάπη Σου πιο αγαπητή σε μένα από τον εαυτό μου, την οικογένειά μου και το κρύο νερό.", "Η ντουά του Dawud (AS) που σχετίζεται από τον Προφήτη ﷺ.", "Η αγάπη του Αλλάχ είναι ο μεγαλύτερος πλούτος."),
        "dua_filal_khayrat" to DuaText("Κάνοντας το καλό και αφήνοντας το κακό", "Ω Αλλάχ, Σου ζητώ να με επιτρέψεις να κάνω καλές πράξεις, να αφήσω τις κακές πράξεις και να αγαπήσω τους φτωχούς, και να με συγχωρήσεις και να με ελεήσεις. Και όταν σκοπεύεις μια δοκιμασία για έναν λαό, πάρε με χωρίς να δοκιμαστώ. Σου ζητώ την αγάπη Σου, την αγάπη όσων Σε αγαπούν και την αγάπη των πράξεων που με φέρνουν κοντά στην αγάπη Σου.", "Ο Αλλάχ δίδαξε αυτή τη ντουέτα στον Προφήτη ﷺ σε ένα όνειρο.", "Ο Προφήτης ﷺ είπε: είναι αλήθεια, γι' αυτό μάθε το και διδάξε το."),
        "dua_bi_ilmikal_ghayb" to DuaText("Αφήστε με να ζήσω όσο η ζωή είναι καλή", "Ω Αλλάχ, με τη γνώση Σου για το αόρατο και τη δύναμή Σου πάνω στη δημιουργία - κράτησέ με ζωντανό όσο ξέρεις ότι η ζωή είναι καλύτερη για μένα και πάρε με όταν ξέρεις ότι ο θάνατος είναι καλύτερος για μένα. Ω Αλλάχ, Σου ζητώ να σε φοβάσαι κατ' ιδίαν και δημόσια, τον λόγο της αλήθειας στην ικανοποίηση και στον θυμό, και το μέτρο στη φτώχεια και στον πλούτο.", "Η προσευχή του Ammar ibn Yasir (RA) (εναρκτήριο μέρος).", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά σε προσευχή."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Ω Αλλάχ, σε ζητώ, γιατί σε Σένα ανήκει όλος ο έπαινος. δεν υπάρχει θεός εκτός από Εσένα, τον Δωρητή των ευεργεσιών, τον Δημιουργό των ουρανών και της γης. Ω Κάτοχος Μεγαλειότητας και Τιμής, Ω Αειθαλής Ζωντανός, Ω Συντηρητής!", "Ο Προφήτης ﷺ είπε ότι αυτός ο άνθρωπος έκανε ντουέτα με το Μεγαλύτερο Όνομα του Αλλάχ.", "Μια ντουέτα που έγινε με αυτό το Όνομα απαντάται."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Ω Αλλάχ, σε ζητώ, γιατί δίνω μαρτυρία ότι είσαι ο Αλλάχ. δεν υπάρχει θεός εκτός από Εσένα, τον Ένας, τον Αυτάρκη, που ούτε γεννά ούτε γεννιέται, και δεν υπάρχει κανένας συγκρίσιμος με Αυτόν.", "Ο Προφήτης ﷺ είπε ότι αυτός ο άνθρωπος ρώτησε τον Αλλάχ με το Μεγαλύτερο Όνομά Του.", "Όταν του ζητηθεί, δίνει. όταν καλείται από αυτό, απαντά."),
        "dua_thabbitni_hadiyan" to DuaText("Κάνε με σταθερό, καθοδηγημένο και οδηγό", "Ω Αλλάχ, κάνε με σταθερό, και κάνε με κάποιον που καθοδηγεί και καθοδηγείται.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά για τον Jarir (RA) (για τον εαυτό σας πείτε «thabbitni»).", "Η αρχική dua για το Jarir (RA) χρησιμοποιεί τις λέξεις «thabbit-hu»."),
        "dua_rabbighfir_tub_alayya" to DuaText("Συγχώρεσέ με και Δέξου τη Μετάνοιά Μου", "Κύριε μου, συγχώρεσέ με και δέξου τη μετάνοιά μου. Πράγματι, Εσύ είσαι ο Αποδέκτης της μετάνοιας, ο Ελεήμων.", "Εκατό φορές σε μια μόνο συνεδρίαση - η πρακτική του Προφήτη ﷺ.", "Οι σύντροφοι μέτρησαν τον Προφήτη ﷺ λέγοντάς το εκατό φορές σε μία συνεδρίαση."),
        "dua_rafiq_ala" to DuaText("Δέηση του ετοιμοθάνατου", "Ω Αλλάχ, συγχώρεσέ με, ελέησέ με και ένωσε με με τον Ύψιστο Σύντροφο.", "Η τελευταία ντουέτα του Προφήτη ﷺ — για να πει ο άρρωστος για τον εαυτό του.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουέτα τη στιγμή του θανάτου του."),
        "dua_la_bas_tahur" to DuaText("Παρηγορώντας τον άρρωστο: Κάθαρση", "Κανένα κακό. είναι κάθαρση (από τις αμαρτίες), αν θέλει ο Αλλάχ.", "Να παρηγορεί τους αρρώστους κατά την επίσκεψη.", "Ο Προφήτης ﷺ το είπε όταν επισκεπτόταν τον άρρωστο."),
        "dua_talqeen" to DuaText("Ταλκίν για τον ετοιμοθάνατο", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ.", "Απαγγείλετε το kalimah κοντά σε έναν ετοιμοθάνατο (μην τον αναγκάζετε να το πουν).", "Όποιος τα τελευταία λόγια είναι «La ilaha illallah» θα μπει στον Παράδεισο (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Αντί να Ευχόμαστε για Θάνατο", "Ω Αλλάχ, κράτησέ με ζωντανό όσο η ζωή είναι καλύτερη για μένα, και πάρε με όταν ο θάνατος είναι καλύτερος για μένα.", "Αντί να εύχεσαι τον θάνατο στα δύσκολα.", "Ο Προφήτης ﷺ απαγόρευσε την επιθυμία για θάνατο και αντ' αυτού το δίδαξε."),
        "dua_for_one_i_cursed" to DuaText("Για κάποιον που πληγώνω με τις λέξεις", "Ω Αλλάχ, οποιονδήποτε πιστό τον έχω προσβάλει, κάνε τον ένα μέσο εγγύτητας σε Σένα την Ημέρα της Ανάστασης.", "Για κάποιον που μίλησες άσχημα με θυμό.", "Μια ντουέτα του Προφήτη ﷺ."),
        "dua_praising_someone" to DuaText("Όταν επαινείτε κάποιον", "Θεωρώ ότι ο τάδε και ο άλλος είναι έτσι, και ο Αλλάχ είναι ο Υπολογιστής του, και δεν εγγυώμαι για την αγνότητα κανενός ενώπιον του Αλλάχ.", "Όταν επαινείτε κάποιον, αντί να υπερβάλλετε.", "Ο Προφήτης ﷺ δίδαξε αυτή την εθιμοτυπία του επαίνου."),
        "dua_being_praised" to DuaText("Όταν σε επαινούν", "Ω Αλλάχ, μη με παίρνεις λογαριασμό για όσα λένε και συγχώρεσέ με για όσα δεν ξέρουν.", "Όταν ακούει κανείς τον εαυτό του να επαινείται — η πρακτική ενός Companion (RA).", "Ένας τρόπος για να αποφύγετε την αλαζονεία όταν τον επαινείτε."),
        "dua_non_muslim_sneezes" to DuaText("Όταν ένας μη μουσουλμάνος φτερνίζεται", "Είθε ο Αλλάχ να σας καθοδηγήσει και να διορθώσει τις υποθέσεις σας.", "Όταν ένας μη μουσουλμάνος φτερνίζεται και λέει «Alhamdulillah».", "Οι Εβραίοι φτερνίζονταν κοντά στον Προφήτη ﷺ ελπίζοντας ότι θα έλεγε «Yarhamukallah» και θα το έλεγε αυτό."),
        "dua_reply_ahl_kitab_salam" to DuaText("Απαντώντας στο Salam of People of the Book", "Και πάνω σου.", "Όταν οι Άνθρωποι του Βιβλίου χαιρετούν με σαλάμ.", "Η οδηγία του Προφήτη ﷺ."),
        "dua_fasting_invited" to DuaText("Όταν προσκεκλημένος ενώ νηστεύεις", "νηστεύω.", "Όταν είσαι καλεσμένος ενώ νηστεύεις, ή όταν κάποιος σε μαλώνει.", "Αν ο νηστευτής δεχτεί πρόσκληση, θα πρέπει να προσευχηθεί για τον οικοδεσπότη."),
        "dua_for_who_gave_drink" to DuaText("Για όποιον με τάιζε", "Ω Αλλάχ, τάισε αυτόν που με τάισε και δώσε να πιει αυτόν που μου έδωσε να πιω.", "Για όποιον σου δίνει φαγητό ή ποτό.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά για αλ-Μικντάντ (RA)."),
        "dua_eid_greeting" to DuaText("Χαιρετισμός Eid", "Είθε ο Αλλάχ να δεχτεί (καλές πράξεις) από εμάς και από εσάς.", "Ο ένας στον άλλο την ημέρα του Eid — η πρακτική των ευγενών συντρόφων (RA).", "Οι σύντροφοι το είπαν αυτό όταν συναντήθηκαν το Eid."),
        "dua_wedding_night" to DuaText("Για τη νύφη μετά τον Νίκα", "Ω Αλλάχ, Σου ζητώ το καλό της και το καλό της φύσης με το οποίο τη δημιούργησες, και ζητώ καταφύγιο σε Σένα από το κακό της και το κακό της φύσης με το οποίο τη δημιούργησες.", "Μετά το νίκα, βάζοντας το χέρι στο μέτωπο της γυναίκας.", "Η διδασκαλία του Προφήτη ﷺ — ευλογία στο γάμο."),
        "dua_istisqa_ibadak" to DuaText("Ποτίστε τους υπηρέτες και τα ζώα σας", "Ω Αλλάχ, δώσε νερό στους δούλους Σου και τα ζώα Σου, διάδωσε το έλεός Σου και δώσε ζωή στη νεκρή γη Σου.", "Ζητώντας βροχή (istisqa).", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά για βροχή."),
        "dua_seeing_clouds" to DuaText("Βλέποντας τα σκοτεινά σύννεφα", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από το κακό του.", "Βλέποντας μαύρα σύννεφα στον ουρανό. αν βρέχει, πείτε «Allahumma sayyiban nafi'a».", "Όταν έβλεπε σύννεφα, ο Προφήτης ﷺ άφηνε αυτό που έκανε και έκανε αυτή τη ντουά."),
        "dua_jamarat" to DuaText("Λιθοβολισμός του Τζαμαράτ", "Ο Αλλάχ είναι ο Μεγαλύτερος.", "Με κάθε πεταμένο βότσαλο.", "Ο Προφήτης ﷺ είπε τακμπίρ με κάθε βότσαλο, και μετά το πρώτο και το δεύτερο τζαμρά κοίταξε την Κιμπλά και έκανε μια μακρά ντουά."),
        "dua_rabbi_ainni" to DuaText("Κύριε μου, Βοήθησέ με και όχι εναντίον Μου", "Κύριε μου, βοήθησέ με και μη βοηθάς τους άλλους εναντίον μου, δώσε μου τη νίκη και μη χαρίζεις σε άλλους τη νίκη εναντίον μου, σχεδίασε με και μη με σχεδιάζεις, καθοδήγησέ με και κάνε την καθοδήγηση εύκολη για μένα, και βοήθησέ με ενάντια σε όποιον με αδικεί.", "Μια περιεκτική ντουέτα του Προφήτη ﷺ (εναρκτήριο μέρος).", "Μια ντουέτα που συγκεντρώνει κάθε βοήθεια στη θρησκεία και σε αυτόν τον κόσμο."),
        "dua_ati_nafsi_taqwaha" to DuaText("Χάρισε στην ψυχή μου ευσέβεια", "Ω Αλλάχ, χάρισε στην ψυχή μου την ευσέβειά της και καθάρισέ την, γιατί Εσύ είσαι ο καλύτερος για να την εξαγνίσεις. Είστε ο Φύλακας και ο Κύριός του.", "Για αναμόρφωση και κάθαρση του εαυτού.", "Ο Προφήτης ﷺ συνήθιζε να κάνει αυτή τη ντουά."),
        "dua_iqsim_lana_khashyatik" to DuaText("Δώσε μας τέτοιο φόβο για σένα", "Ω Αλλάχ, δώσε μας αρκετό φόβο για Σένα για να μπούμε ανάμεσά μας και να Σε παρακούουμε, αρκετή υπακοή για να μας φέρεις στον Παράδεισο Σου και αρκετή βεβαιότητα για να μας διευκολύνεις τις συμφορές αυτού του κόσμου. Ας απολαύσουμε την ακοή μας, την όρασή μας και τη δύναμή μας όσο μας κρατάς ζωντανούς και τα κάνεις να μας ξεπερνούν. Λάβετε εκδίκηση από αυτούς που μας αδικούν, βοηθήστε μας ενάντια στους εχθρούς μας, μην αφήσετε τη συμφορά μας να είναι στη θρησκεία μας, μην κάνετε αυτόν τον κόσμο το μεγαλύτερο μέλημά μας ή το όριο της γνώσης μας και μην βάζετε πάνω μας αυτούς που δεν θα μας δείξουν έλεος.", "Όταν σηκωνόταν από μια συγκέντρωση — ο Προφήτης ﷺ σπάνια σηκωνόταν χωρίς να κάνει αυτή τη ντουά.", "Μια ολοκληρωμένη ντουέτα για το καλό της θρησκείας, αυτού του κόσμου και του επέκεινα."),
        "dua_infani_bima_allamtani" to DuaText("Ωφέλησέ με με όσα μου έμαθες", "Ω Αλλάχ, ωφέλησέ με με ό,τι με δίδαξες, δίδαξέ με τι θα με ωφελήσει και αύξησέ με στη γνώση.", "Κατά την αναζήτηση γνώσης ή πριν από τη μελέτη.", "Μια δόξα για ωφέλιμη γνώση και δράση βάσει αυτής."),
    )
}
